'use strict';

/**
 * Surgical cleanup: remove false OUT flows generated by log 6745
 * ("Faction loan item send") from historical DB records.
 *
 * What it does (all in one transaction):
 *  1. Reads affected item_ids + total qty from activity WHERE log_type = 6745
 *  2. Subtracts that qty from item_totals.out_qty (floor at 0)
 *  3. Deletes item_sources rows WHERE source = 'Faction Loaned'
 *  4. Deletes activity rows WHERE log_type = 6745
 *
 * What it does NOT touch:
 *  - manual_adjustments
 *  - processed_logs
 *  - bazaar_totals / display_totals / market_totals / transfers
 *  - Any other tables
 *
 * Run: node inventory-monitor/fix-faction-loan.js
 * Then restart the server so in-memory state reloads from the fixed DB.
 */

const fs   = require('fs');
const path = require('path');
const { Pool } = require('pg');

// Read DB credentials from root .env (real env vars take precedence).
const env = {};
try {
  fs.readFileSync(path.join(__dirname, '..', '.env'), 'utf8').split(/\r?\n/).forEach(line => {
    const m = line.match(/^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)\s*$/);
    if (m && !(m[1] in process.env)) env[m[1]] = m[2].replace(/^["']|["']$/g, '');
  });
} catch { /* no .env file */ }

const DB = {
  host:     process.env.DB_HOST     || env.DB_HOST,
  port:     parseInt(process.env.DB_PORT || env.DB_PORT || '5432', 10),
  database: process.env.DB_NAME     || env.DB_NAME,
  user:     process.env.DB_USER     || env.DB_USER,
  password: process.env.DB_PASS     || env.DB_PASS,
};

if (!DB.host || !DB.database || !DB.user) {
  console.error('[fix-faction-loan] PostgreSQL not configured — set DB_HOST / DB_NAME / DB_USER in .env');
  process.exit(1);
}

(async () => {
  const pool   = new Pool(DB);
  const client = await pool.connect();
  try {
    // Preview: what would be cleaned up?
    const preview = await client.query(`
      SELECT item_id, item_name, SUM(qty) AS total_out
      FROM activity
      WHERE log_type = 6745
      GROUP BY item_id, item_name
      ORDER BY item_id
    `);

    if (preview.rowCount === 0) {
      console.log('[fix-faction-loan] No log_type=6745 rows found in activity — nothing to clean up.');
      return;
    }

    console.log(`[fix-faction-loan] Found ${preview.rowCount} item(s) with false OUT flows from log 6745:`);
    preview.rows.forEach(r =>
      console.log(`  item_id=${r.item_id}  name="${r.item_name}"  false_out_qty=${r.total_out}`)
    );

    await client.query('BEGIN');

    // 1. Subtract false out_qty from item_totals (floor at 0 — never go negative)
    const update = await client.query(`
      UPDATE item_totals it
      SET
        out_qty    = GREATEST(it.out_qty - agg.total_out, 0),
        updated_at = now()
      FROM (
        SELECT item_id, SUM(qty) AS total_out
        FROM activity
        WHERE log_type = 6745
        GROUP BY item_id
      ) agg
      WHERE it.item_id = agg.item_id
    `);
    console.log(`[fix-faction-loan] Updated item_totals: ${update.rowCount} row(s)`);

    // 2. Delete the broken item_sources rows (source='Faction Loaned' is 6745-only)
    const srcDel = await client.query(`
      DELETE FROM item_sources WHERE source = 'Faction Loaned'
    `);
    console.log(`[fix-faction-loan] Deleted item_sources: ${srcDel.rowCount} row(s) (source='Faction Loaned')`);

    // 3. Delete the false activity entries
    const actDel = await client.query(`
      DELETE FROM activity WHERE log_type = 6745
    `);
    console.log(`[fix-faction-loan] Deleted activity: ${actDel.rowCount} row(s) (log_type=6745)`);

    await client.query('COMMIT');
    console.log('[fix-faction-loan] Done. Restart the server to reload in-memory state from the corrected DB.');
  } catch (e) {
    await client.query('ROLLBACK').catch(() => {});
    console.error('[fix-faction-loan] Error — rolled back:', e.message);
    process.exitCode = 1;
  } finally {
    client.release();
    await pool.end();
  }
})();
